<?php
require __DIR__.'/_init.php';
$types=['hero'=>'Hero','text'=>'Text / split content','image_text'=>'Image and text','feature_grid'=>'Feature cards','article_grid'=>'Article cards','country_grid'=>'Country guides','review_grid'=>'Testimonials','faq_list'=>'FAQs','stats'=>'Stats / highlights','cta'=>'Call to action'];
$id=(int)($_GET['id']??0);$item=null;if($id){$q=db()->prepare('SELECT * FROM sections WHERE id=?');$q->execute([$id]);$item=$q->fetch();if(!$item)redirect(url('admin/sections.php'));}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';if($action==='delete'){db()->prepare('DELETE FROM sections WHERE id=?')->execute([(int)$_POST['id']]);flash('Section deleted.');redirect(url('admin/sections.php'));}$type=$_POST['type']??'text';if(!isset($types[$type]))$type='text';$title=trim($_POST['title']??'');$eyebrow=trim($_POST['eyebrow']??'');$body=trim($_POST['body']??'');$image=trim($_POST['image']??'');$button=trim($_POST['button_label']??'');$buttonUrl=trim($_POST['button_url']??'');$theme=in_array($_POST['theme']??'',['default','soft','dark'],true)?$_POST['theme']:'default';$limit=max(1,min(24,(int)($_POST['item_limit']??6)));$sort=(int)($_POST['sort_order']??0);$enabled=isset($_POST['enabled'])?1:0;if(!$title){flash('Section heading is required.');redirect(url('admin/sections.php'.($id?'?id='.$id:'?new=1')));}if($id){$q=db()->prepare('UPDATE sections SET type=?,title=?,eyebrow=?,body=?,image=?,button_label=?,button_url=?,theme=?,item_limit=?,sort_order=?,enabled=? WHERE id=?');$q->execute([$type,$title,$eyebrow,$body,$image,$button,$buttonUrl,$theme,$limit,$sort,$enabled,$id]);}else{$q=db()->prepare('INSERT INTO sections(type,title,eyebrow,body,image,button_label,button_url,theme,item_limit,sort_order,enabled) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$type,$title,$eyebrow,$body,$image,$button,$buttonUrl,$theme,$limit,$sort,$enabled]);}flash('Section saved.');redirect(url('admin/sections.php'));}
$msg=$_SESSION['_flash']??'';unset($_SESSION['_flash']);$items=db()->query('SELECT * FROM sections ORDER BY sort_order,id')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Homepage sections</title><link rel="stylesheet" href="<?=e(url('assets/css/admin.css'))?>"><link rel="icon" type="image/svg+xml" href="<?=e(url('favicon.svg'))?>"></head><body><div class="shell"><?php require __DIR__.'/_nav.php';?><main><div class="top"><div><small>VISUAL WEBSITE BUILDER</small><h1>Homepage sections</h1></div><a href="<?=e(url('admin/sections.php?new=1'))?>">＋ Add section</a></div><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif;?>
<?php if($id||isset($_GET['new'])):?><form method="post" class="panel editor"><?=csrf_field()?><label>Section layout<select name="type"><?php foreach($types as $k=>$v):?><option value="<?=e($k)?>" <?=($item['type']??'text')===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><label>Section heading<input name="title" required value="<?=e($item['title']??'')?>" placeholder="A heading visitors will see"></label><label>Eyebrow / small label<input name="eyebrow" value="<?=e($item['eyebrow']??'')?>"></label><label>Description / content<textarea name="body" rows="5"><?=e($item['body']??'')?></textarea><small>For Stats / highlights, use one item per line in this format: 10K|Community members</small></label><label>Image URL<input id="image-url" name="image" value="<?=e($item['image']??'')?>"></label><div class="upload"><input type="file" id="section-file" accept="image/jpeg,image/png,image/webp,image/gif"><button type="button" id="section-upload" class="secondary">Upload image</button><span id="upload-status"></span></div><div class="two"><label>Button label<input name="button_label" value="<?=e($item['button_label']??'')?>"></label><label>Button URL<input name="button_url" value="<?=e($item['button_url']??'')?>" placeholder="Leave blank to use registration URL"></label></div><div class="two"><label>Background<select name="theme"><?php foreach(['default'=>'White','soft'=>'Soft green','dark'=>'Dark green'] as $k=>$v):?><option value="<?=$k?>" <?=($item['theme']??'default')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Cards to show<input type="number" min="1" max="24" name="item_limit" value="<?=e((string)($item['item_limit']??6))?>"></label></div><div class="two"><label>Display order<input type="number" name="sort_order" value="<?=e((string)($item['sort_order']??10))?>"></label><label class="check-label"><input type="checkbox" name="enabled" value="1" <?=(!isset($item['enabled'])||$item['enabled'])?'checked':''?>> Visible on website</label></div><button class="primary">Save section</button><a class="secondary" href="<?=e(url('admin/sections.php'))?>">Cancel</a></form>
<?php else:?><p class="intro">Add sections, change their order, switch layouts, or hide a section without deleting it. Article, country and testimonial cards automatically use your published content.</p><div class="section-list"><?php foreach($items as $s):?><div class="section-row"><div class="drag">⠿</div><div class="section-info"><b><?=e($s['title'])?></b><small><?=e($types[$s['type']]??$s['type'])?> · Order <?=e((string)$s['sort_order'])?> · <?=($s['enabled']?'Visible':'Hidden')?></small></div><a href="<?=e(url('admin/sections.php?id='.$s['id']))?>">Edit</a><form method="post" onsubmit="return confirm('Delete this section?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="danger">Delete</button></form></div><?php endforeach;?></div><?php endif;?></main></div><script>const up=document.getElementById('section-upload');if(up)up.onclick=async()=>{let f=document.getElementById('section-file').files[0],s=document.getElementById('upload-status');if(!f){s.textContent='Choose an image';return;}let d=new FormData();d.append('image',f);d.append('_csrf',<?=json_encode(csrf_token())?>);s.textContent='Uploading…';try{let r=await fetch(<?=json_encode(url('admin/upload.php'))?>,{method:'POST',body:d}),j=await r.json();if(!r.ok)throw Error(j.error);document.getElementById('image-url').value=j.url;s.textContent='Uploaded';}catch(e){s.textContent=e.message;}};</script></body></html>